CREATE TABLE usage_events (account_id VARCHAR(64) NOT NULL, request_id VARCHAR(64) NOT NULL, occurred_at DATETIME NOT NULL, billing_mode VARCHAR(16) NOT NULL CHECK (billing_mode IN ('request', 'bytes', 'tokens')), request_bytes INTEGER NOT NULL CHECK (request_bytes >= 0), response_bytes INTEGER NOT NULL CHECK (response_bytes >= 0), input_tokens INTEGER NOT NULL CHECK (input_tokens >= 0), output_tokens INTEGER NOT NULL CHECK (output_tokens >= 0), charged_sat INTEGER NOT NULL CHECK (charged_sat > 0), PRIMARY KEY (account_id, request_id, occurred_at), FOREIGN KEY (account_id, request_id) REFERENCES debits(account_id, request_id));
CREATE INDEX usage_events_time_idx ON usage_events (occurred_at DESC);
